'use strict';
const DATA=JSON.parse(document.getElementById('portal-data').textContent);
const C=DATA.curriculum,R=DATA.research,S=DATA.simulations,Y=DATA.syntax,J=DATA.java;
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fold=v=>String(v).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const txt=v=>typeof v==='string'?v:Array.isArray(v)?v.map(txt).join('\n'):v&&typeof v==='object'?Object.entries(v).map(([k,val])=>`${k}: ${txt(val)}`).join('\n'):String(v??'');
const para=v=>txt(v).split(/\n\n+/).filter(Boolean).map(x=>`<p>${esc(x).replace(/\n/g,'<br>')}</p>`).join('');
const ul=arr=>`<ul>${(arr||[]).map(x=>`<li>${esc(txt(x))}</li>`).join('')}</ul>`;
const ol=arr=>`<ol>${(arr||[]).map(x=>`<li>${esc(txt(x))}</li>`).join('')}</ol>`;
const link=(u,t)=>/^https?:\/\//.test(u||'')?`<a href="${esc(u)}" target="_blank" rel="noopener noreferrer">${esc(t||u)} ↗</a>`:esc(t||u);
const KEY='staff-lab-v1';
const blank=()=>({version:1,done:{},cards:{},notes:{},scores:{},attempts:[],skills:{},visits:[],editors:{},week:1});
let toastTimeout;
function sanitizeState(v){
 if(!v||typeof v!=='object'||v.version!==1)throw Error('Formato inválido');
 const out=blank();
 for(const k of ['done','cards','notes','scores','skills','editors']){
  if(!v[k]||typeof v[k]!=='object'||Array.isArray(v[k]))throw Error('Dados inválidos');
  for(const [id,val] of Object.entries(v[k])){
   if(id.length>150||['__proto__','constructor','prototype'].includes(id))throw Error('Chave inválida');
   if(k==='done'){if(typeof val!=='boolean')throw Error('Lição inválida');out[k][id]=val}
   if(k==='notes'||k==='editors'){if(typeof val!=='string'||val.length>200000)throw Error('Texto inválido');out[k][id]=val}
   if(k==='scores'||k==='skills'){if(!Number.isInteger(val)||val<0||val>4)throw Error('Nota inválida');out[k][id]=val}
   if(k==='cards'){if(!val||typeof val!=='object'||!Number.isFinite(val.due)||!Number.isFinite(val.interval)||!Number.isInteger(val.reps)||val.reps<0)throw Error('Cartão inválido');out[k][id]={due:val.due,interval:val.interval,reps:val.reps,lastRating:Number(val.lastRating)||0}}
  }
 }
 if(!Array.isArray(v.visits)||!v.visits.every(d=>typeof d==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(d)))throw Error('Datas inválidas');out.visits=[...new Set(v.visits)];
 if(!Array.isArray(v.attempts)||v.attempts.length>10000)throw Error('Histórico inválido');
 out.attempts=v.attempts.map(a=>{if(!a||typeof a!=='object'||!S.some(s=>s.id===a.id)||!Number.isFinite(Date.parse(a.date))||!Number.isInteger(a.score)||!Number.isInteger(a.max)||a.score<0||a.max<1||a.score>a.max||typeof a.retro!=='string')throw Error('Tentativa inválida');return {id:a.id,date:new Date(a.date).toISOString(),score:a.score,max:a.max,retro:a.retro.slice(0,200000)}});
 out.week=Number.isInteger(v.week)&&v.week>0?v.week:1;return out;
}
let state=blank(),storageOk=true;
try{const stored=localStorage.getItem(KEY);if(stored)state=sanitizeState(JSON.parse(stored))}catch(e){storageOk=false}
const today=()=>{const d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')};
const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(state))}catch(e){if(storageOk)toast('O navegador bloqueou o salvamento. Exporte seu progresso.');storageOk=false}};
if(!state.visits.includes(today())){state.visits.push(today());save()}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>$('#toast').classList.remove('visible'),3300)}
const paths={home:'M3 10 12 3l9 7v10H3z M9 20v-7h6v7',roadmap:'M4 4h16v16H4z M8 8h8 M8 12h8 M8 16h5',learn:'M3 4h7l2 2 2-2h7v15h-7l-2 2-2-2H3z M12 6v15',code:'m8 7-5 5 5 5 M16 7l5 5-5 5 M14 4l-4 16',simulations:'M6 3h12v18H6z M9 7h6 M9 11h6 M9 15h3',review:'M4 7h13v14H4z M8 3h13v14 M8 11h5 M8 15h5',systems:'M9 3h6v5H9z M3 16h6v5H3z M15 16h6v5h-6z M12 8v4 M6 16v-4h12v4',progress:'M4 20V10 M10 20V4 M16 20v-8 M22 20H2',sources:'M5 3h11l4 4v14H5z M15 3v5h5 M9 12h7 M9 16h7',arrow:'M4 12h16 M14 6l6 6-6 6',check:'m5 12 4 4 10-10',clock:'M12 4a8 8 0 1 0 0 16 8 8 0 1 0 0-16 M12 7v6h4'};
paths.syntax=paths.code;paths.java=paths.code;
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.learn}"/></svg>`;
const navItems=[['home','Visão geral'],['roadmap','Meu plano de estudo'],['learn','Mapa do conhecimento'],['code','Laboratório de código'],['syntax','Dojo anti-branco'],['java','Java de cabeça'],['simulations','Arena de simulações'],['review','Memória & revisão'],['systems','Arquitetura em prática'],['progress','Minha evolução'],['sources','Pesquisa & fontes']];
$('#nav').innerHTML=navItems.map(([id,label])=>`<a href="#${id}" data-nav="${id}">${icon(id)}${label}${id==='simulations'?'<span class="nav-count">60</span>':''}</a>`).join('');
const allCards=[...J.cards.map(c=>({id:javaKey(c.id),q:c.question,a:c.answer+'\n\n'+c.code+'\n\nArmadilha: '+c.pitfall,category:'Java • '+c.category})),...(C.flashcards||[]).map((c,i)=>({...c,id:'c'+(c.id??i)})),...S.flatMap(s=>(s.flashcards||[]).map((c,i)=>({...c,id:`s${s.id}-${i}`,q:s.title+' — '+c.q,category:s.category})))];
const dueCards=()=>allCards.filter(c=>(state.cards[c.id]?.due||0)<=Date.now());
const completeLessons=()=>Object.values(state.done).filter(Boolean).length;
const lessonCount=()=>C.modules.reduce((a,m)=>a+m.lessons.length,0);
const pct=()=>Math.round(100*completeLessons()/Math.max(1,lessonCount()));
const brief=s=>s.brief.split(' Ensaio autoral inspirado em problemas de engenharia financeira;')[0];
const pageHead=(eyebrow,title,desc,extra='')=>`<div class="page-heading"><div><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p>${desc}</p></div>${extra}</div>`;
let route='home',routeId='',caseRound=0,caseTab='brief',flashIndex=0,flashShown=false,reviewMode='due',reviewCategory='all',labMode='reference';
let timer={caseId:null,round:0,remaining:1800,running:false,end:0};
function go(name,id=''){location.hash=name+(id?'/'+id:'')}
function refreshChrome(){const d=dueCards().length;$('#due-count').textContent=d;$('#streak').innerHTML=`${state.visits.length} ${state.visits.length===1?'dia por aqui':'dias por aqui'}<small>Pratique. Explique. Repita.</small>`;$$('[data-nav]').forEach(e=>e.classList.toggle('active',e.dataset.nav===route));$('#crumb').textContent=navItems.find(x=>x[0]===route)?.[1]||'Visão geral'}
let lastCaseId='';
function render(){const p=location.hash.slice(1).split('/');route=navItems.some(x=>x[0]===p[0])?p[0]:'home';try{routeId=decodeURIComponent(p[1]||'')}catch{routeId=''}if(route==='simulations'&&routeId&&lastCaseId!==routeId){caseRound=0;caseTab='brief';lastCaseId=routeId}$('#sidebar').classList.remove('open');$('.mobile-menu').setAttribute('aria-expanded','false');refreshChrome();const views={home:homeView,roadmap:roadmapView,learn:learnView,code:codeView,syntax:syntaxView,java:javaView,simulations:simulationsView,review:reviewView,systems:systemsView,progress:progressView,sources:sourcesView};$('#main').innerHTML=views[route]();document.title=`${navItems.find(x=>x[0]===route)[1]} • Staff Lab`;if(route==='simulations'&&!routeId)applyCaseFilters();if(route==='systems')updateSystem();if(route==='review')updateFlash();if(route==='java')updateJavaGrid();if(!storageOk)toast('Salvamento local indisponível. Use Exportar progresso.');window.scrollTo({top:0,behavior:'instant'})}
function heroArt(){return `<svg class="hero-art" viewBox="0 0 320 230" aria-hidden="true"><defs><linearGradient id="glass" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#ffffff" stop-opacity=".22"/><stop offset="1" stop-color="#ffffff" stop-opacity=".04"/></linearGradient></defs><g fill="none" stroke="#be83f4" stroke-width="1" opacity=".45"><path d="M56 60 152 110 253 54 M56 60v102l96 48 101-54V54 M152 110v100 M56 162l197-108 M56 60l197 96"/><path d="M17 112 151 36l139 73-137 82z" stroke-dasharray="3 6"/></g><g fill="url(#glass)" stroke="#c897f1" stroke-opacity=".5"><rect x="111" y="76" width="84" height="70" rx="13"/><rect x="34" y="40" width="46" height="39" rx="9"/><rect x="230" y="33" width="46" height="39" rx="9"/><rect x="230" y="139" width="46" height="39" rx="9"/><rect x="34" y="144" width="46" height="39" rx="9"/></g><g fill="none" stroke="#e8d3ff" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="m141 98-10 12 10 12 M165 98l10 12-10 12 M157 95l-7 30"/><path d="M48 51h18v15H48z M51 56h12 M244 45h18 M244 51h18 M244 57h12 M48 158l8-5 8 5v12H48z M244 151h18v15h-18z M248 155h10 M248 160h7"/></g><g fill="#d8b9fa"><circle cx="152" cy="37" r="3"/><circle cx="18" cy="112" r="3"/><circle cx="291" cy="109" r="3"/><circle cx="152" cy="210" r="3"/></g><text x="111" y="175" fill="#d4b2f6" font-size="8" font-family="monospace" letter-spacing="2">BUILD YOUR NEXT LEVEL</text></svg>`}
function homeView(){const first=C.modules.find(m=>m.lessons.some((l,i)=>!state.done[`${m.id}-${i}`]))||C.modules[0];const next=S.find(s=>!state.attempts.some(a=>a.id===s.id))||S[0];return `${pageHead('VAMOS CONSTRUIR SEU PRÓXIMO PASSO','De bom engenheiro a referência.','Um laboratório para pensar, construir e comunicar no nível Staff.','<span class="date-chip">Pesquisa • 26 out 2026</span>')}<section class="hero"><div class="hero-copy"><span class="eyebrow">SUA JORNADA COMEÇA AQUI</span><h2>Domine o raciocínio.<br><span>Construa sua confiança.</span></h2><p>Fundamentos que ficam. Código que você explica. Decisões que resistem a perguntas difíceis. Um passo de cada vez, até o nível Staff.</p><div class="button-row"><a class="btn white" href="#roadmap">Começar minha preparação ${icon('arrow')}</a><a class="btn ghost small" href="#simulations">Explorar as 60 simulações</a></div></div>${heroArt()}</section><div class="stats">${[[C.modules.length,'módulos de conhecimento','learn'],[60,'processos para simular','simulations'],[C.codeLabs.length,'laboratórios de código','code'],[allCards.length,'cartões de memória','review']].map(([n,t,i])=>`<div class="stat"><div class="stat-icon">${icon(i)}</div><span><strong>${n}</strong><small>${t}</small></span></div>`).join('')}</div><div class="grid-2"><section><div class="section-head"><div><h2>Seu caminho até Staff</h2><p>Base sólida. Prática intencional. Visão de sistema.</p></div><a href="#learn">Ver mapa completo →</a></div><div class="card">${[['01','Fundamentos que sustentam decisões','Algoritmos, tipos, testes e complexidade','Fundamentos'],['02','Do código ao sistema','Concorrência, dados, APIs e padrões','Construção'],['03','Escala, confiabilidade e influência','Sistemas distribuídos e liderança técnica','Staff']].map(([n,t,d,b])=>`<a class="path-row" href="#learn"><div class="path-icon">${icon(n==='01'?'code':n==='02'?'systems':'progress')}</div><div><h3>${t}</h3><p>${d}</p></div><span class="arrow">↗</span></a>`).join('')}</div></section><section><div class="section-head"><div><h2>Pequenos passos, todos os dias</h2><p>Seu progresso fica neste navegador.</p></div><span class="pill">${pct()}% da trilha</span></div><div class="card"><div class="progress-label"><span>${completeLessons()} de ${lessonCount()} lições praticadas</span><span>${pct()}%</span></div><div class="progress-track"><span style="width:${pct()}%"></span></div><div class="week-row"><span class="check-circle">1</span>Recuperar de memória • 15 min</div><div class="week-row"><span class="check-circle">2</span>Resolver e explicar • 45 min</div><div class="week-row"><span class="check-circle">3</span>Registrar um erro • 10 min</div><a class="btn primary small" style="width:100%" href="#learn/${esc(first.id)}">Continuar: ${esc(first.title)} →</a><div class="callout">✦ <strong>Prática vence releitura.</strong> Feche a resposta, tente sozinho e só depois compare.</div></div></section></div><div class="section-head section-space"><div><h2>Escolha seu próximo desafio</h2><p>Prepare-se para resolver, explicar e defender suas decisões.</p></div></div><div class="grid-3"><article class="card mini-card"><span class="pill">ARENA • 120 MIN</span><h3>${esc(next.title)}</h3><p>Quatro rodadas, perguntas de aprofundamento e rubrica de autoavaliação.</p><div class="card-foot"><span>Simulação autoral ${String(next.id).padStart(2,'0')}/60</span><a href="#simulations/${next.id}" aria-label="Abrir simulação">↗</a></div></article><article class="card mini-card"><span class="pill green">REVISÃO ATIVA</span><h3>Faça o conhecimento ficar.</h3><p>Perguntas de sintaxe, decisões e invariantes. Revele a resposta depois de tentar.</p><div class="card-foot"><span>${dueCards().length} cartões disponíveis hoje</span><a href="#review" aria-label="Abrir revisão">↗</a></div></article><article class="card mini-card"><span class="pill blue">DOJO ANTI-BRANCO</span><h3>O primeiro passo nunca precisa ser perfeito.</h3><p>Treine imports, sintaxe e a ordem de construir uma solução sem olhar.</p><div class="card-foot"><span>36 treinos • 12 receitas</span><a href="#syntax" aria-label="Abrir dojo anti-branco">↗</a></div></article></div><section class="java-home-banner"><div><span class="eyebrow">NOVO • JAVA DE CABEÇA</span><h3>Sintaxe que você consegue reconstruir.</h3><p>${J.cards.length} cartões com imports, métodos, classes e exemplos executáveis. Escreva antes de revelar.</p></div><a class="btn primary" href="#java">Treinar Java →</a></section><p class="welcome-note">Preparação independente, sem garantia de aprovação. As 60 simulações são autorais; o processo real depende da vaga e da equipe. <a href="#sources">Entenda as evidências ↗</a></p>`}
function roadmapView(){return `${pageHead('DA BASE À PRÁTICA','Um plano que sai do papel.','Comece pelo diagnóstico, escolha uma especialização e use os critérios de saída para avançar. As 12 semanas são um ritmo sugerido, não uma promessa de prontidão.')}<div class="grid-3">${[['01','Faça seu diagnóstico','Resolva um lab sem consulta, desenhe um fluxo e explique um incidente. Registre as lacunas.','progress'],['02','Escolha seu eixo','Domine o núcleo comum e aprofunde a especialização da vaga. Ajuste o plano ao seu ponto de partida.','learn'],['03','Treine sob restrição','Faça cada simulação sem gabarito. Depois corrija, registre erros e repita com requisitos novos.','simulations']].map(([n,t,d,r])=>`<div class="card"><span class="eyebrow">PASSO ${n}</span><h3>${t}</h3><p>${d}</p><a href="#${r}">Abrir ferramenta →</a></div>`).join('')}</div><div class="notice"><strong>Ritmo sugerido:</strong> 5 dias × 90 min, uma simulação de 120 min e uma revisão semanal. O banco completo tem 120 horas de rodadas, além das correções; o ciclo inicial usa uma simulação por semana. Se a base ainda não estiver estável, repita a semana. A senioridade vem de decisões e experiência demonstrável, além de estudo.</div><div class="timeline section-space">${C.plan.map((w,i)=>`<section class="card week-card"><span class="eyebrow">SEMANA ${w.week||i+1}</span><h3>${esc(w.title)}</h3>${para(w.focus)}<div class="reading">${ul(w.deliverables)}</div><div class="callout"><strong>Critério para avançar:</strong> ${esc(txt(w.gate))}</div></section>`).join('')}</div><h2 class="section-space">Playbooks para a hora de praticar</h2><div class="grid-equal">${C.playbooks.map(p=>`<article class="card reading"><h3 style="margin-top:0">${esc(p.title)}</h3>${ol(p.steps)}<details><summary>Ver exemplo de aplicação</summary><div>${para(p.example)}</div></details></article>`).join('')}</div>`}
function learnView(){const m=C.modules.find(x=>String(x.id)===routeId);if(!m)return `${pageHead('MAPA DO CONHECIMENTO','Profundidade começa na base.','Estude o núcleo comum e explore a trilha relevante à vaga. Cada lição tem explicação, exercício, resposta e critério de domínio.')}<div class="filters"><input id="module-search" placeholder="Filtrar módulos: concorrência, mobile, dados…" aria-label="Filtrar módulos"></div><div class="grid-3" id="module-grid">${C.modules.map((m,n)=>{const c=m.lessons.filter((l,i)=>state.done[`${m.id}-${i}`]).length;return `<article class="card module-card" data-text="${esc((m.title+' '+m.summary+' '+m.level).toLowerCase())}"><span class="pill">${esc(m.level)}</span><span class="tiny" style="float:right">${String(n+1).padStart(2,'0')}</span><h3 style="margin-top:18px">${esc(m.title)}</h3><p>${esc(m.summary)}</p><div class="progress-label"><span>${c}/${m.lessons.length} lições</span><span>${Math.round(100*c/m.lessons.length)}%</span></div><div class="progress-track"><span style="width:${100*c/m.lessons.length}%"></span></div><a class="btn small section-space" href="#learn/${esc(m.id)}">Estudar módulo →</a></article>`}).join('')}</div>`;return `${pageHead(esc(m.level),esc(m.title),esc(m.summary),'<a class="btn small" href="#learn">← Todos os módulos</a>')}<div class="split"><div class="list-panel">${C.modules.map(x=>`<a class="list-item ${x.id===m.id?'active':''}" href="#learn/${esc(x.id)}">${esc(x.title)}<small>${esc(x.level)} • ${x.lessons.length} lições</small></a>`).join('')}</div><article class="card reading"><div class="notice" style="margin-top:0">Leia → feche → explique em voz alta → resolva → compare. Só marque uma lição depois de praticar sem olhar.</div>${m.lessons.map((l,i)=>`<section class="lesson"><span class="lesson-number">LIÇÃO ${i+1}</span><h2>${esc(l.title)}</h2>${para(l.body)}<h3>Veja o raciocínio</h3>${para(l.example)}<div class="callout"><strong>Sua vez</strong><br>${esc(txt(l.exercise))}</div><details><summary>Comparar com a resposta comentada</summary><div>${para(l.answer)}</div></details><h3>Você consegue explicar?</h3>${ul(l.checklist)}<label class="completion"><input type="checkbox" data-lesson="${esc(m.id)}-${i}" ${state.done[`${m.id}-${i}`]?'checked':''}>Pratiquei e consigo explicar sem consulta</label></section>`).join('')}<h3>Documentação de referência</h3><div class="tiny break-word">${(m.sourceUrls||[]).map(u=>link(u)).join('<br>')}</div></article></div>`}
function codeView(){const lab=C.codeLabs.find(x=>String(x.id)===routeId)||C.codeLabs[0];return `${pageHead('LABORATÓRIO DE CÓDIGO','Sintaxe vira memória com prática.','Leia o contrato, escreva sua solução e rode os testes no ambiente local indicado. O editor abaixo guarda seu rascunho; não executa código.')}<div class="split"><div class="list-panel">${C.codeLabs.map(l=>`<a class="list-item ${l.id===lab.id?'active':''}" href="#code/${esc(l.id)}">${esc(l.title)}<small>${esc(l.language)}</small></a>`).join('')}</div><article class="card reading lab-panel"><span class="pill">${esc(lab.language)}</span><h2 style="margin-top:17px">${esc(lab.title)}</h2>${para(lab.why)}<h3>O problema</h3>${para(lab.problem)}<div class="tabs"><button class="tab ${labMode==='reference'?'active':''}" data-lab-tab="reference">Referência comentada</button><button class="tab ${labMode==='draft'?'active':''}" data-lab-tab="draft">Meu rascunho</button></div>${labMode==='reference'?`<div class="code-toolbar"><span>Exemplo de estudo • não é código de produção</span><button class="btn small" data-copy-lab="${esc(lab.id)}">Copiar código + testes</button></div><pre><code>${esc(lab.code)}</code></pre>`:`<textarea class="code-editor" spellcheck="false" aria-label="Seu rascunho de código" data-editor="${esc(lab.id)}" placeholder="Escreva sem olhar a referência. Declare entradas, saídas e invariantes primeiro.">${esc(state.editors[lab.id]||'')}</textarea><p class="tiny">Rascunho salvo automaticamente neste navegador. Não executado aqui.</p>`}<h3>Como rodar</h3><pre><code>${esc(txt(lab.run))}</code></pre><p class="tiny">Verificação deste exemplo: ${esc(txt(lab.validation||'Referência revisada, execução não confirmada para este runtime.'))}</p><details><summary>Testes e casos de borda</summary><div><pre><code>${esc(txt(lab.tests))}</code></pre></div></details><h3>Explique cada decisão</h3>${ol(lab.walkthrough)}<div class="callout"><strong>Complexidade:</strong> ${esc(lab.complexity)}</div><h3>Armadilhas para evitar</h3>${ul(lab.pitfalls)}<h3>Recuperação de sintaxe em 4 passos</h3><ol><li>Escreva a assinatura e um exemplo mínimo de entrada e saída.</li><li>Nomeie o estado e a estrutura de dados antes do laço.</li><li>Implemente o caminho feliz; depois acrescente erros e limites.</li><li>Se esquecer uma API, diga o contrato desejado, escreva pseudocódigo e confirme se pode consultar a documentação.</li></ol><div class="tiny break-word">${link(lab.sourceUrl,'Documentação oficial')}</div></article></div>`}
function simulationsView(){if(routeId)return sessionView(S.find(s=>String(s.id)===routeId)||S[0]);return `${pageHead('60 PROCESSOS. 240 RODADAS.','Pratique o processo inteiro.','Ensaios autorais com quatro rodadas cada: código, arquitetura, incidente e influência. Os tempos são de treino; não representam a agenda oficial do Nubank.')}<div class="notice"><strong>Como usar:</strong> reserve 120 min, responda sem gabarito e peça a alguém para fazer os aprofundamentos. Depois use a rubrica, registre o que faltou e repita com uma restrição diferente. Você pode fazer as quatro rodadas em dias separados.</div><div class="filters"><input id="case-search" aria-label="Buscar simulação" placeholder="Buscar domínio, requisito ou falha…"><select id="case-category" aria-label="Filtrar especialização"><option value="all">Todas as especializações</option>${[...new Set(S.map(s=>s.category))].map(c=>`<option>${esc(c)}</option>`).join('')}</select><select id="case-level" aria-label="Filtrar dificuldade"><option value="all">Todos os níveis</option>${[...new Set(S.map(s=>s.difficulty))].map(c=>`<option>${esc(c)}</option>`).join('')}</select><button class="btn small" data-action="random-case">↻ Surpreenda-me</button></div><p class="result-total" id="case-total"></p><div class="grid-3" id="cases-grid"></div>`}
function applyCaseFilters(){if(!$('#cases-grid'))return;const q=fold($('#case-search').value||''),cat=$('#case-category').value,lvl=$('#case-level').value;const matches=S.filter(s=>(cat==='all'||s.category===cat)&&(lvl==='all'||s.difficulty===lvl)&&fold(JSON.stringify(s)).includes(q));$('#case-total').textContent=`${matches.length} ${matches.length===1?'simulação':'simulações'} • ${state.attempts.length} tentativas registradas`;$('#cases-grid').innerHTML=matches.length?matches.map(s=>`<article class="card case-card"><header><span class="pill">${esc(s.category)}</span><span class="case-id">${String(s.id).padStart(2,'0')}</span></header><h3>${esc(s.title)}</h3><p>${esc(brief(s))}</p><div class="button-row"><span class="pill gray">${esc(s.difficulty)}</span>${state.attempts.some(a=>a.id===s.id)?'<span class="pill green">Praticado</span>':''}</div><footer><span>4 rodadas • ${s.minutes} min</span><a class="btn small" href="#simulations/${s.id}">Entrar na arena →</a></footer></article>`).join(''):'<div class="empty">Nenhum resultado. Tente outro termo ou especialização.</div>'}
function sessionView(s){const r=s.rounds[caseRound]||s.rounds[0];if(timer.caseId!==s.id||timer.round!==caseRound){timer={caseId:s.id,round:caseRound,remaining:r.minutes*60,running:false,end:0}}return `${pageHead(`SIMULAÇÃO AUTORAL ${String(s.id).padStart(2,'0')} • ${esc(s.category)}`,esc(s.title),esc(brief(s)),'<a class="btn small" href="#simulations">← Todas</a>')}<section class="card reading" style="max-width:none"><div class="session-head"><div><span class="pill">${esc(s.difficulty)}</span><p class="tiny" style="margin:10px 0 0">Entregue raciocínio verificável, não uma resposta decorada.</p></div><div class="timer-controls"><span class="clock" id="clock">${formatTime(timer.remaining)}</span><button class="btn small" data-action="timer">${timer.running?'Pausar':'Iniciar'}</button><button class="btn small" data-action="reset-timer">Reiniciar</button></div></div><div class="rounds">${s.rounds.map((x,i)=>`<button class="round ${i===caseRound?'active':''}" data-round="${i}"><small>RODADA ${i+1} • ${x.minutes} MIN</small><b>${esc(x.name)}</b></button>`).join('')}</div><div class="tabs">${[['brief','Desafio & rascunho'],['solution','Gabarito & aprofundamentos'],['score','Rubrica & registro']].map(([k,t])=>`<button class="tab ${caseTab===k?'active':''}" data-case-tab="${k}">${t}</button>`).join('')}</div>${caseTab==='brief'?`<div class="grid-equal"><div><h3 style="margin-top:0">Contrato do problema</h3>${ul(s.requirements)}</div><div><h3 style="margin-top:0">Restrições</h3>${ul(s.constraints)}</div></div><h2>${esc(r.name)}</h2>${para(r.prompt)}<div class="callout"><strong>Seu entregável:</strong> ${esc(txt(r.deliverable))}</div><h3>Rascunhe antes de revelar</h3><textarea class="answer-input" data-case-note="${s.id}-${caseRound}" placeholder="Perguntas de clarificação, contrato, hipótese, solução, testes e concessões…" aria-label="Rascunho da rodada">${esc(state.notes[`${s.id}-${caseRound}`]||'')}</textarea><p class="tiny">Salvo neste navegador. Código e diagramas são rascunhos; não são executados ou avaliados automaticamente.</p><h3>Perguntas do entrevistador</h3>${ul(r.followups)}<div class="button-row"><button class="btn primary" data-case-tab="solution">Compare seu raciocínio →</button>${caseRound<3?`<button class="btn" data-round="${caseRound+1}">Próxima rodada →</button>`:''}</div>`:caseTab==='solution'?`<div class="notice">Não existe arquitetura única. O gabarito é uma referência para discutir garantias, custo, operação e risco.</div><h3>O que uma resposta forte nesta rodada demonstra</h3>${ul(r.strongAnswer)}<h3>Estratégia do caso</h3>${para(s.solution.approach)}${ol(s.solution.steps)}<div class="callout"><strong>Complexidade e escala:</strong> ${esc(s.solution.complexity)}</div><div class="grid-equal"><div><h3>Testes indispensáveis</h3>${ul(s.solution.tests)}</div><div><h3>Concessões que você deve defender</h3>${ul(s.solution.tradeoffs)}</div></div><h3>Erros que enfraquecem a resposta</h3>${ul(s.pitfalls)}<button class="btn primary" data-case-tab="score">Avaliar minha tentativa →</button>`:`<h3 style="margin-top:0">Avalie evidências, não sensação</h3><p>Escala de treino: 0 = não demonstrei; 1 = precisei de muita ajuda; 2 = parcial; 3 = independente; 4 = expliquei alternativas e limites. Não é a rubrica oficial do Nubank.</p>${s.rubric.map((r,i)=>`<div class="score-row"><div><h4>${esc(r.criterion)}</h4><p><strong>Forte:</strong> ${esc(r.excellent)}</p><p><strong>Lacuna:</strong> ${esc(r.weak)}</p></div><select data-score="${s.id}-${i}" aria-label="Nota para ${esc(r.criterion)}">${[0,1,2,3,4].map(n=>`<option value="${n}" ${Number(state.scores[`${s.id}-${i}`]||0)===n?'selected':''}>${n} — ${['Não demonstrei','Com muita ajuda','Parcial','Independente','Com profundidade'][n]}</option>`).join('')}</select></div>`).join('')}<h3>O que vou corrigir na próxima tentativa?</h3><textarea class="note-area" data-case-note="retro-${s.id}" aria-label="Retrospectiva da simulação" placeholder="Uma decisão fraca, uma lacuna de conhecimento e uma ação concreta para corrigir…">${esc(state.notes[`retro-${s.id}`]||'')}</textarea><div class="button-row section-space"><button class="btn primary" data-save-attempt="${s.id}">Registrar tentativa</button><a class="btn" href="#progress">Ver minha evolução</a></div><p class="tiny section-space">Registre depois de concluir as quatro rodadas. Uma nota alta aqui não prevê aprovação.</p>`}</section>`}
function formatTime(s){return `${Math.floor(s/60).toString().padStart(2,'0')}:${(s%60).toString().padStart(2,'0')}`}
setInterval(()=>{if(!timer.running)return;timer.remaining=Math.max(0,Math.ceil((timer.end-Date.now())/1000));if($('#clock'))$('#clock').textContent=formatTime(timer.remaining);if(timer.remaining===0){timer.running=false;toast('Tempo da rodada encerrado. Registre o que ficou incompleto.');const b=$('[data-action="timer"]');if(b)b.textContent='Iniciar'}},500);
function currentFlashList(){let a=reviewMode==='due'?dueCards():allCards;return reviewCategory==='all'?a:a.filter(c=>c.category===reviewCategory)}
function reviewView(){return `${pageHead('RECUPERAÇÃO ATIVA','Você aprende quando tenta lembrar.','Leia a pergunta, responda em voz alta e só então revele. O agendamento usa intervalos simples como ferramenta de estudo, sem promessa de memória perfeita.')}<div class="filters"><select id="review-mode" aria-label="Modo de revisão"><option value="due" ${reviewMode==='due'?'selected':''}>Revisões disponíveis hoje</option><option value="all" ${reviewMode==='all'?'selected':''}>Todos os cartões</option></select><select id="review-category" aria-label="Categoria de revisão"><option value="all">Todos os assuntos</option>${[...new Set(allCards.map(c=>c.category))].filter(Boolean).sort().map(c=>`<option ${reviewCategory===c?'selected':''}>${esc(c)}</option>`).join('')}</select><button class="btn small" data-action="shuffle-card">↻ Trocar cartão</button></div><div class="review-wrap"><div id="flash-meta" class="progress-label"></div><button class="flash-card" id="flash-card" data-action="flip"></button><div class="review-actions" id="review-actions">${[[0,'Não lembrei','Rever em 10 min'],[1,'Com esforço','Rever em 1 dia'],[2,'Lembrei','Rever em 3 dias'],[3,'Expliquei bem','Rever em 7+ dias']].map(([n,t,d])=>`<button data-rate="${n}">${t}<small>${d}</small></button>`).join('')}</div><p class="tiny" style="text-align:center">Espaço: revelar • 1–4: avaliar depois de revelar. Faça 10–20 cartões por bloco; a lista não é uma obrigação diária. Intervalos fáceis crescem até 60 dias.</p><div class="callout"><strong>Para sintaxe:</strong> digite o trecho de memória, compile, leia o erro e reescreva do zero. Para arquitetura: desenhe o fluxo e explique o que acontece quando cada dependência falha.</div></div><div class="grid-3 section-space"><div class="card"><h3>01. Recupere</h3><p>Antes de reler, tente responder. O esforço mostra a lacuna real.</p></div><div class="card"><h3>02. Corrija</h3><p>Compare com a referência e registre a diferença. Evite repetir a resposta sem entender.</p></div><div class="card"><h3>03. Varie</h3><p>Mude a entrada, a escala ou a falha. Explique por que sua solução ainda funciona.</p></div></div>`}
function updateFlash(){const a=currentFlashList();flashIndex=a.length?flashIndex%a.length:0;const c=a[flashIndex];$('#flash-meta').innerHTML=`<span>${a.length} cartões nesta seleção</span><span>${Object.keys(state.cards).length}/${allCards.length} já revisados</span>`;$('#flash-card').innerHTML=c?`<span class="pill">${esc(c.category||'Conhecimento')}</span><h2>${esc(c.q)}</h2>${flashShown?`<div class="flash-answer">${esc(c.a)}</div>`:'<span class="tiny">Pense antes de clicar para revelar ↗</span>'}`:'<span class="eyebrow">FEITO POR HOJE</span><h2>Nenhuma revisão pendente.</h2><p class="muted">Mude para “Todos os cartões” para praticar mais ou volte quando o próximo estiver disponível.</p>';$$('[data-rate]').forEach(b=>b.disabled=!c||!flashShown);$('#flash-card').disabled=!c;$('#flash-card').setAttribute('aria-expanded',String(flashShown))}
function rateCard(n){if(!flashShown)return;const c=currentFlashList()[flashIndex];if(!c)return;const old=state.cards[c.id]||{interval:0,reps:0},days=n===0?10/1440:n===1?1:n===2?3:Math.min(60,Math.max(7,(old.interval||3)*2));state.cards[c.id]={due:Date.now()+days*86400000,interval:days,reps:old.reps+1,lastRating:n};save();flashShown=false;if(reviewMode==='all')flashIndex++;updateFlash();refreshChrome();toast(n===0?'Vamos recuperar este cartão em 10 minutos.':'Revisão registrada. Próximo cartão.')} 
const failures={normal:{title:'Fluxo nominal',nodes:[],body:'O cliente envia uma chave de idempotência. A API valida o comando e executa a movimentação e a inserção na outbox na mesma transação. Um publicador envia o evento. O consumidor atualiza sua projeção de forma idempotente.',invariant:'Débitos e créditos somam zero na mesma moeda. Uma operação concluída não reaparece como uma segunda movimentação.',ask:'Onde ficam a chave de idempotência e a resposta persistida? Como uma chave repetida com payload diferente é rejeitada?'},duplicate:{title:'Requisição duplicada',nodes:[0,1],body:'A mesma chave chega novamente. Uma restrição única coordena chamadas concorrentes. Para o mesmo payload, devolva o resultado persistido; para payload diferente, retorne conflito. Uma consulta “se não existe, insira” fora de transação tem corrida.',invariant:'Uma chave identifica um comando dentro de um escopo explícito, com fingerprint e política de retenção definidos.',ask:'A primeira chamada ainda está em andamento. A segunda espera, recebe estado pendente ou tenta competir? Como evitar débitos duplicados?'},timeout:{title:'Resposta perdida',nodes:[0,1],body:'O commit pode ter ocorrido mesmo que o cliente tenha recebido timeout. O cliente consulta o status ou repete a mesma chave. Não assuma que timeout significa falha financeira e não crie automaticamente uma chave nova.',invariant:'O resultado financeiro é determinado pelo estado durável, não pela entrega da resposta HTTP.',ask:'O provedor externo não aceita idempotência. Como modelar estado desconhecido e reconciliação antes de tentar de novo?'},broker:{title:'Broker indisponível',nodes:[3],body:'A transação local já registrou a outbox. O publicador acumula tentativas com backoff e observa a idade do evento mais antigo. Defina limites de backlog e degradação. Outbox não elimina duplicatas: um crash após publicar e antes de marcar pode republicar.',invariant:'Nenhum evento confirmado localmente depende de um dual write não atômico para ser recuperável.',ask:'Por quanto tempo o sistema aguenta o backlog? Em que ponto você limita novos comandos ou degrada funcionalidades?'},consumer:{title:'Consumidor reinicia',nodes:[4],body:'O consumidor pode aplicar o efeito e reiniciar antes de confirmar o offset. O reprocessamento exige deduplicação persistida na mesma transação do efeito local, ou operação naturalmente idempotente. Efeitos externos precisam de protocolo próprio.',invariant:'A garantia fim a fim depende do limite transacional e do destino. “Exactly once” no broker não garante todo efeito externo.',ask:'Um replay de seis meses deve reenviar notificações? Como separar reconstrução de projeção de efeitos irreversíveis?'},order:{title:'Eventos fora de ordem',nodes:[3,4],body:'Defina ordenação por entidade e versione mudanças. O consumidor rejeita versões antigas ou armazena lacunas para recuperação. Particionar por conta ajuda a ordenar uma conta, mas uma transferência envolve duas contas e precisa de coordenação adicional.',invariant:'A projeção não pode regredir para um estado antigo. Não existe ordenação global gratuita.',ask:'O que acontece se uma conta concentrar tráfego? Como preservar garantias ao reparticionar o stream?'}};
let systemFailure='normal';
function systemsView(){return `${pageHead('LABORATÓRIO DE ARQUITETURA','A parte difícil é quando algo falha.','Explore um modelo didático de movimentação financeira. Use o raciocínio também em pedidos, reservas, faturamento e outros fluxos com efeitos duráveis.')}<section class="card reading" style="max-width:none"><div class="section-head"><h2>Comando → estado durável → evento → projeção</h2><span class="pill">MODELO DIDÁTICO</span></div><div class="flow-diagram" id="flow-diagram"></div><div class="failure-controls">${Object.entries(failures).map(([k,v])=>`<button data-failure="${k}" class="${k===systemFailure?'active':''}">${v.title}</button>`).join('')}</div><div id="failure-explanation"></div><div class="notice">Diagrama de raciocínio, sem simulação de tráfego real. Em produção, autenticação, autorização, reconciliação, auditoria, retenção e operação também fazem parte do sistema.</div></section><div class="grid-equal section-space"><article class="card reading"><h3 style="margin-top:0">Seu roteiro de system design</h3>${ol(['Pergunte objetivo, usuário, escopo e o que não está sendo resolvido.','Defina invariantes, SLOs, volume médio/pico e limites de latência.','Desenhe o menor fluxo ponta a ponta e modele os estados.','Escolha armazenamento, chaves, índices, limites transacionais e contratos.','Explore duplicação, atraso, indisponibilidade, concorrência e recuperação.','Defina métricas, alertas, rollout, rollback, custo e donos.','Feche com concessões, riscos remanescentes e próximos experimentos.'])}</article><article class="card reading"><h3 style="margin-top:0">Estimativa com unidade</h3><p>Um exemplo de treino: 10 milhões de operações por dia ÷ 86.400 ≈ 116 operações/s em média. Com pico hipotético de 10×, planeje cerca de 1.160/s antes de medir.</p><p>Se cada registro ocupa 1 KB, são aproximadamente 10 GB/dia de dados brutos. Réplicas, índices, logs e retenção aumentam esse valor. A hipótese precisa ser validada.</p><div class="callout"><strong>Pergunta Staff:</strong> qual decisão realmente muda com essa estimativa? Evite fazer contas que não afetam sua arquitetura.</div><a href="#simulations">Praticar em um cenário →</a></article></div><section class="card reading section-space" style="max-width:none"><h3 style="margin-top:0">Contrato financeiro mínimo</h3><pre><code>POST /transfers\nIdempotency-Key: 8c…\n{ from_account, to_account, amount_minor: 1250, currency: "BRL" }\n\ncreated → pending → confirmed\n                  ↘ rejected\n                  ↘ unknown → reconciliation\n\n• amount_minor é inteiro; moeda e escala são explícitas\n• atualização de saldo respeita concorrência e limite de crédito\n• transferência interna: débito + crédito na mesma transação\n• estorno é uma nova operação auditável, sem apagar o histórico</code></pre><p>Essas são escolhas para o exercício, não uma descrição da arquitetura interna do Nubank. As referências de transações, Kafka e confiabilidade estão nos módulos e na pesquisa.</p></section>`}
function updateSystem(){const f=failures[systemFailure];$('#flow-diagram').innerHTML=[['Cliente','chave do comando'],['API','valida + coordena'],['Banco + outbox','mesma transação'],['Broker','entrega e replay'],['Consumidor','efeito + deduplicação']].map(([a,b],i)=>`${i?'<span class="flow-arrow" aria-hidden="true">→</span>':''}<div class="flow-node ${f.nodes.includes(i)?'failure':i===2?'highlight':''}">${a}<small>${b}</small></div>`).join('');$('#failure-explanation').innerHTML=`<h3>${f.title}</h3><p>${f.body}</p><div class="callout"><strong>Invariante:</strong> ${f.invariant}</div><h3>Pergunta de aprofundamento</h3><p>${f.ask}</p>`;$$('[data-failure]').forEach(e=>e.classList.toggle('active',e.dataset.failure===systemFailure))}
const skillAxes=[['coding','Código e testes','Resolvo um problema novo, explico complexidade e testo limites.'],['design','Arquitetura e dados','Defino invariantes, contratos, limites e falhas.'],['operations','Operação e confiabilidade','Investigo incidentes, mitigo e faço rollout seguro.'],['influence','Influência e comunicação','Conecto decisões a impacto e coordeno além da minha equipe.'],['specialty','Especialização','Discuto em profundidade a área da vaga e suas concessões.'],['english','Comunicação em inglês','Explico decisões, faço perguntas e sinalizo incerteza.']];
function progressView(){return `${pageHead('MINHA EVOLUÇÃO','Evidências de que você está melhorando.','Use critérios observáveis e registre suas lacunas. Estes indicadores organizam seu estudo; não estimam sua chance de contratação.')}<div class="stats">${[[completeLessons(),`de ${lessonCount()} lições praticadas`,'learn'],[state.attempts.length,'tentativas registradas','simulations'],[Object.keys(state.cards).length,'cartões já revisados','review'],[state.visits.length,'dias de acesso','progress']].map(([n,t,i])=>`<div class="stat"><div class="stat-icon">${icon(i)}</div><span><strong>${n}</strong><small>${t}</small></span></div>`).join('')}</div><div class="notice">Escala de autodiagnóstico: 0 = não sei começar; 1 = com muita orientação; 2 = resolvo com lacunas; 3 = independente; 4 = ensino, comparo alternativas e explico limites. Reavalie após uma simulação ou revisão externa.</div><div class="readiness-grid">${skillAxes.map(([k,t,d])=>`<section class="card meter-card"><label for="axis-${k}">${t} <span class="pill" id="value-${k}">${state.skills[k]||0}/4</span></label><input type="range" min="0" max="4" step="1" value="${state.skills[k]||0}" id="axis-${k}" data-skill="${k}"><p>${d}</p></section>`).join('')}</div><section class="card section-space"><h2>Diário de erros e decisões</h2><p class="muted">Registre: situação → hipótese → erro → evidência → correção → próximo exercício.</p><textarea class="note-area" data-case-note="journal" aria-label="Diário de erros" placeholder="Hoje eu assumi que um timeout significava falha. Preciso modelar estado desconhecido e reconciliação…">${esc(state.notes.journal||'')}</textarea></section><section class="card section-space"><div class="section-head"><h2>Histórico de simulações</h2><button data-action="backup">Exportar progresso ↗</button></div>${state.attempts.length?`<div class="table-wrap"><table><thead><tr><th>Data</th><th>Simulação</th><th>Autoavaliação</th><th>Próxima melhoria</th></tr></thead><tbody>${state.attempts.slice().reverse().map(a=>`<tr><td>${esc(new Date(a.date).toLocaleDateString('pt-BR'))}</td><td><a href="#simulations/${a.id}">${esc(S.find(s=>s.id===a.id)?.title||a.id)}</a></td><td>${esc(a.score)} / ${esc(a.max)}</td><td>${esc(a.retro||'Sem observação')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Sua primeira tentativa aparece aqui.<br><a href="#simulations">Comece por um desafio →</a></div>'}</section><section class="card reading section-space" style="max-width:none"><h3 style="margin-top:0">Antes da entrevista</h3>${ul(['Confirme com o recrutador etapas, duração, linguagem, ambiente e regras de consulta/IA.','Tenha exemplos reais de decisões arquiteturais, incidentes, conflitos e impacto entre equipes.','Teste editor, compilador, câmera, microfone, compartilhamento e alternativa de conexão.','Treine dizer: “Vou reformular o problema e validar minhas hipóteses antes de implementar”.','Se der branco: pause, escreva entrada/saída, faça um exemplo pequeno e narre o próximo passo.','Durante a entrevista, use somente ferramentas e apoios permitidos pelas regras do processo.'])}<p class="tiny">Os rascunhos ficam no armazenamento local deste navegador. Apagar dados do navegador pode removê-los. O backup JSON pode ser importado na versão online ou no HTML local.</p></section>`}
function sourcesView(){return `${pageHead('PESQUISA • 26 OUTUBRO 2026','O que sabemos. E com qual evidência.','Levantamento de fontes públicas acessíveis. Não é um inventário de todos os comentários existentes, nem revela perguntas privadas ou garante que uma etapa será aplicada.')}<div class="legend"><span class="pill green">Oficial: processo, vagas e engenharia</span><span class="pill amber">Relato: experiência individual</span><span class="pill blue">Documentação técnica</span><span class="pill gray">Simulações: autorais</span></div><div class="notice"><strong>Leitura correta:</strong> vagas e guias oficiais informam a preparação, mas podem mudar. Relatos ajudam a explorar variações e não provam a política atual. Confirme o formato da sua vaga com recrutamento. Links externos precisam de internet.</div><h2 class="section-space">Sinais que orientam a preparação</h2><div class="grid-equal">${R.findings.map(f=>`<article class="card reading"><h3 style="margin-top:0">${esc(f.title)}</h3>${para(f.body)}<div class="tiny">${(f.sourceIds||[]).map(id=>{const s=R.sources.find(x=>x.id===id);return s?link(s.url,s.title):''}).join(' · ')}</div></article>`).join('')}</div><h2 class="section-space">Formatos possíveis de processo</h2><div class="grid-equal">${R.process.map(p=>`<article class="card"><h3>${esc(p.title)}</h3>${para(p.description)}<span class="pill gray">${esc(txt(p.evidence))}</span><div class="tiny section-space">${(p.sourceIds||[]).map(id=>{const s=R.sources.find(x=>x.id===id);return s?link(s.url,s.title):''}).join('<br>')}</div></article>`).join('')}</div><section class="card reading section-space" style="max-width:none"><h3 style="margin-top:0">Perguntas que reduzem incerteza</h3>${ul(R.recruiterQuestions)}</section><div class="section-head section-space"><h2>Biblioteca de evidências</h2><span class="tiny">${R.sources.length} fontes • acesso em 26/10/2026</span></div><div class="filters"><input id="source-search" aria-label="Filtrar fontes" placeholder="Buscar fonte, especialização ou assunto…"><select id="source-kind" aria-label="Tipo de fonte"><option value="all">Todos os tipos</option><option value="official">Fontes oficiais</option><option value="report">Relatos públicos</option><option value="technical">Documentação técnica</option></select></div><div class="grid-equal" id="source-grid">${R.sources.map(s=>`<article class="card source-card" data-source-kind="${esc(s.kind)}" data-text="${esc(JSON.stringify(s).toLowerCase())}"><div class="button-row"><span class="pill ${s.kind==='official'?'green':s.kind==='report'?'amber':'blue'}">${s.kind==='official'?'Oficial':s.kind==='report'?'Relato público':'Documentação'}</span><span class="tiny">${esc(s.date||'Sem data informada')}</span></div><h3 class="section-space">${link(s.url,s.title)}</h3>${para(s.summary)}<p class="tiny">${esc(s.caveat||'Verifique atualização e contexto na fonte original.')}</p></article>`).join('')}</div>`}
let syntaxMode='drills';
function syntaxView(){const drill=Y.drills.find(d=>String(d.id)===routeId)||Y.drills[0];return `${pageHead('DOJO ANTI-BRANCO','Não espere lembrar. Treine recuperar.','Pratique imports, assinatura, tipos, fluxo e testes em blocos pequenos. Você não precisa carregar todas as APIs na cabeça: construa um ponto de partida confiável e saiba como confirmar o restante.')}<div class="stress-bar"><div><h3>Deu branco? Volte ao próximo passo observável.</h3><p>Entrada → saída → exemplo → assinatura → estado → fluxo → teste. Diga o que sabe antes de procurar o nome exato de uma API.</p></div><button class="btn white" data-action="reset-mind">Abrir protocolo de 30 s ↗</button></div><div class="tabs"><button class="tab ${syntaxMode==='drills'?'active':''}" data-syntax-tab="drills">${Y.drills.length} treinos de sintaxe</button><button class="tab ${syntaxMode==='recipes'?'active':''}" data-syntax-tab="recipes">${Y.recipes.length} receitas para começar</button><button class="tab ${syntaxMode==='method'?'active':''}" data-syntax-tab="method">Meu método anti-branco</button></div>${syntaxMode==='drills'?`<div class="split"><div class="list-panel">${Y.drills.map(d=>`<a href="#syntax/${esc(d.id)}" class="list-item ${d.id===drill.id?'active':''}">${esc(d.title)}<small>${esc(d.language)}${d.framework?' • '+esc(d.framework):''}</small></a>`).join('')}</div><article class="card reading"><div class="button-row"><span class="pill">${esc(drill.language)}</span><span class="pill gray">${esc(drill.level)}</span></div><h2 class="section-space">${esc(drill.title)}</h2>${para(drill.prompt)}<pre><code>${esc(drill.skeleton.replace(/\{\{([^}]+)\}\}/g,(m,k)=>'⟦'+k+'⟧'))}</code></pre><div id="syntax-slots">${drill.slots.map((s,i)=>`<div class="syntax-slot"><div><label for="syntax-field-${i}"><strong>⟦${esc(s.key)}⟧</strong> ${esc(s.label)}</label><details><summary>Uma pista</summary><div class="slot-hint">${esc(s.hint)}</div></details></div><div><input id="syntax-field-${i}" data-syntax-slot="${esc(s.key)}" value="${esc(state.notes['syntax-'+drill.id+'-'+s.key]||'')}" aria-describedby="syntax-feedback-${i}" spellcheck="false" autocomplete="off" placeholder="Tente de memória"><span id="syntax-feedback-${i}" class="slot-hint"></span></div></div>`).join('')}</div><div class="button-row section-space"><button class="btn primary" data-check-syntax="${esc(drill.id)}">Verificar lacunas</button><button class="btn" data-clear-syntax="${esc(drill.id)}">Repetir do zero</button></div><div class="syntax-result" id="syntax-result" aria-live="polite"></div><p class="tiny">Compara com as formas previstas neste exercício, normalizando espaços. Não compila e não determina se outras soluções são semanticamente corretas.</p><details><summary>Revelar referência completa e explicação</summary><div><pre><code>${esc(drill.reference)}</code></pre>${para(drill.explanation)}<h3>Armadilhas</h3>${ul(drill.pitfalls)}</div></details><div class="callout"><strong>Mais importante que acertar a lacuna:</strong> feche a referência, abra um arquivo vazio e reconstrua o exemplo. Rode localmente e acrescente um teste novo.</div><p class="tiny section-space break-word">${link(drill.sourceUrl,'Documentação de referência')}</p><p class="tiny">Verificação: ${esc(txt(drill.validation||'Revisão estática; execução não confirmada.'))}</p></article></div>`:syntaxMode==='recipes'?`<div class="notice">Receitas pequenas para iniciar um raciocínio. Dependências e versões aparecem no contexto. Não são modelos completos de produção e não substituem a documentação da versão usada.</div><div class="grid-equal">${Y.recipes.map(r=>`<article class="card reading"><span class="pill">${esc(r.language)}</span><h3>${esc(r.title)}</h3>${para(r.context)}<h4>Ordem de construção</h4>${ol(r.sequence)}<details><summary>Abrir código com imports</summary><div><pre><code>${esc(r.code)}</code></pre><button class="btn small" data-copy-recipe="${esc(r.id)}">Copiar receita</button></div></details><h4 class="section-space">Atenção</h4>${ul(r.pitfalls)}<div class="tiny">${link(r.sourceUrl,'Conferir API na documentação')}</div><p class="tiny">Verificação: ${esc(txt(r.validation||'Revisão estática; execução não confirmada.'))}</p></article>`).join('')}</div>`:`<div class="cheat-grid">${[['1 · Contrato','Qual é a entrada? Qual é a saída? Quais erros existem?'],['2 · Exemplo','Faça o menor exemplo concreto e o resultado esperado.'],['3 · Assinatura','Escolha tipos e nomes. Escreva a função ainda vazia.'],['4 · Estado','Preciso de map, set, fila, pilha, contador ou nenhum estado?'],['5 · Fluxo','Implemente uma transformação por vez. Narre a intenção.'],['6 · Teste','Execute exemplo, borda e falha. Depois discuta complexidade.']].map(([a,b])=>`<div class="cheat-cell"><strong>${a}</strong>${b}</div>`).join('')}</div><div class="grid-equal section-space">${Y.protocols.map(p=>`<section class="card reading"><h3 style="margin-top:0">${esc(p.title)}</h3>${ol(p.steps)}</section>`).join('')}<section class="card reading"><h3 style="margin-top:0">Frases que destravam a colaboração</h3>${ul(['“Sei o contrato desta operação, mas não lembro o nome exato da API. Posso consultar a documentação?”','“Vou escrever a transformação em pseudocódigo e converter para a linguagem.”','“Vou resolver o exemplo menor primeiro; depois generalizo.”','“Esta hipótese depende do isolamento do banco. Vou explicitá-la antes de seguir.”','“I know the operation I need; I do not recall the exact API name. May I check the documentation?”'])}</section></div><div class="notice">Confirme previamente quais consultas e ferramentas são permitidas. O portal é para preparação; não presume permissão para assistência durante a entrevista.</div>`}`}
function checkSyntax(id){const d=Y.drills.find(d=>String(d.id)===id);let hit=0;d.slots.forEach((s,i)=>{const input=$('#syntax-field-'+i);const norm=x=>x.trim().replace(/\s+/g,' ');const ok=s.answers.some(a=>norm(a)===norm(input.value));hit+=Number(ok);input.classList.toggle('correct',ok);input.classList.toggle('incorrect',!ok);$('#syntax-feedback-'+i).textContent=ok?'✓ Forma prevista correta':'↻ Reveja esta lacuna ou confira a referência';state.notes['syntax-'+d.id+'-'+s.key]=input.value});state.scores['syntax-'+d.id]=Math.round(4*hit/d.slots.length);save();$('#syntax-result').textContent=`${hit}/${d.slots.length} lacunas nas formas previstas. ${hit===d.slots.length?'Agora reescreva o exemplo do zero em seu editor.':'Use uma pista, tente novamente e explique a diferença.'}`}
function openResetProtocol(){$('#detail-body').innerHTML=`<span class="eyebrow">PROTOCOLO DE RETOMADA</span><h2>Você só precisa encontrar<br>o próximo passo.</h2><div class="reading">${ol(['0–5 s: pare de tentar lembrar tudo de uma vez. Diga: “Vou organizar o raciocínio”.','5–10 s: escreva uma entrada pequena e a saída esperada.','10–15 s: escreva a assinatura e nomeie a estrutura de dados.','15–25 s: faça só a primeira transformação. Pseudocódigo é um ponto de apoio para continuar.','25–30 s: execute mentalmente o exemplo. Se faltar uma API, diga o contrato e pergunte se pode consultar.'])}</div><div class="callout">“Não lembro o nome exato agora, mas preciso de uma operação que agrupe por chave. Vou mostrar o fluxo e confirmar a API.”</div><button class="btn primary section-space" data-action="close-detail">Encontrei meu próximo passo →</button>`;$('#detail-dialog').showModal()}

const searchIndex=[...J.cards.map(c=>({kind:'Java • '+c.category,title:c.title,desc:c.question,to:'java/'+c.id,text:JSON.stringify(c)})),...Y.drills.map(x=>({kind:'Dojo • '+x.language,title:x.title,desc:x.prompt,to:'syntax/'+x.id,text:JSON.stringify(x)})),...C.modules.map(x=>({kind:'Módulo',title:x.title,desc:x.summary,to:'learn/'+x.id,text:JSON.stringify(x)})),...C.codeLabs.map(x=>({kind:'Código • '+x.language,title:x.title,desc:x.problem,to:'code/'+x.id,text:JSON.stringify(x)})),...S.map(x=>({kind:'Simulação • '+x.category,title:x.title,desc:x.brief,to:'simulations/'+x.id,text:JSON.stringify(x)})),...R.sources.map(x=>({kind:'Fonte',title:x.title,desc:x.summary,to:'sources',text:JSON.stringify(x)}))];
function openSearch(){$('#search-dialog').showModal();$('#global-search').value='';search('');setTimeout(()=>$('#global-search').focus(),20)}
function search(q){const words=fold(q.trim()).split(/\s+/).filter(Boolean);let hits=words.length?searchIndex.filter(x=>words.every(w=>fold(x.text).includes(w))).sort((a,b)=>Number(b.title.toLowerCase().includes(q.toLowerCase()))-Number(a.title.toLowerCase().includes(q.toLowerCase()))):searchIndex.slice(0,6);$('#search-results').innerHTML=hits.length?hits.slice(0,30).map(x=>`<button class="search-result" data-search-route="${esc(x.to)}"><span class="pill gray">${esc(x.kind)}</span><div style="margin-top:7px">${esc(x.title)}</div><small>${esc(txt(x.desc).slice(0,140))}</small></button>`).join(''):'<div class="empty">Nenhum resultado. Tente um termo mais curto.</div>'}
function filterSources(){const q=fold($('#source-search').value),k=$('#source-kind').value;$$('.source-card').forEach(e=>e.hidden=!(fold(e.dataset.text).includes(q)&&(k==='all'||e.dataset.sourceKind===k)))}
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
document.addEventListener('click',async e=>{const t=e.target.closest('button,a');if(!t)return;if(t.classList.contains('skip')){e.preventDefault();$('#main').focus();return}if(t.dataset.route){go(t.dataset.route);return}if(t.dataset.action){const a=t.dataset.action;if(a==='menu'){$('#sidebar').classList.toggle('open');t.setAttribute('aria-expanded',String($('#sidebar').classList.contains('open')));}if(a==='search')openSearch();if(a==='reset-mind')openResetProtocol();if(a==='close-search')$('#search-dialog').close();if(a==='close-detail')$('#detail-dialog').close();if(a==='backup')download('staff-lab-progresso.json',JSON.stringify({app:'staff-lab',exportedAt:new Date().toISOString(),state},null,2),'application/json');if(a==='restore')$('#restore-file').click();if(a==='random-case')go('simulations',S[Math.floor(Math.random()*S.length)].id);if(a==='timer'){if(timer.running){timer.remaining=Math.max(0,Math.ceil((timer.end-Date.now())/1000));timer.running=false}else if(timer.remaining>0){timer.end=Date.now()+timer.remaining*1000;timer.running=true}t.textContent=timer.running?'Pausar':'Iniciar'}if(a==='reset-timer'){const s=S.find(x=>x.id===timer.caseId);timer.remaining=s.rounds[timer.round].minutes*60;timer.running=false;render()}if(a==='flip'){flashShown=!flashShown;updateFlash()}if(a==='shuffle-card'){flashIndex=Math.floor(Math.random()*Math.max(1,currentFlashList().length));flashShown=false;updateFlash()}}if(t.dataset.syntaxTab){syntaxMode=t.dataset.syntaxTab;render()}if(t.dataset.checkSyntax)checkSyntax(t.dataset.checkSyntax);if(t.dataset.clearSyntax){const d=Y.drills.find(x=>String(x.id)===t.dataset.clearSyntax);d.slots.forEach(x=>delete state.notes['syntax-'+d.id+'-'+x.key]);save();render()}if(t.dataset.copyRecipe){const r=Y.recipes.find(x=>String(x.id)===t.dataset.copyRecipe);try{await navigator.clipboard.writeText(r.code);toast('Receita copiada.')}catch{download('receita-'+r.id+'.txt',r.code,'text/plain')}}if(t.dataset.searchRoute){$('#search-dialog').close();location.hash=t.dataset.searchRoute}if(t.dataset.labTab){labMode=t.dataset.labTab;render()}if(t.dataset.copyLab){const l=C.codeLabs.find(x=>String(x.id)===t.dataset.copyLab);try{await navigator.clipboard.writeText(l.code+'\n\n'+txt(l.tests));toast('Código e testes copiados.')}catch{download('referencia-'+l.id+'.txt',l.code+'\n\n'+txt(l.tests),'text/plain');toast('Referência baixada como texto.')}}if(t.dataset.round!==undefined){caseRound=Number(t.dataset.round);caseTab='brief';render()}if(t.dataset.caseTab){caseTab=t.dataset.caseTab;render()}if(t.dataset.saveAttempt){const s=S.find(x=>String(x.id)===t.dataset.saveAttempt);state.attempts.push({id:s.id,date:new Date().toISOString(),score:s.rubric.reduce((n,r,i)=>n+Number(state.scores[`${s.id}-${i}`]||0),0),max:4*s.rubric.length,retro:state.notes[`retro-${s.id}`]||''});save();toast('Tentativa registrada. Anote a próxima melhoria.')}if(t.dataset.rate!==undefined)rateCard(Number(t.dataset.rate));if(t.dataset.failure){systemFailure=t.dataset.failure;updateSystem()}});
document.addEventListener('input',e=>{const t=e.target;if(t.dataset.syntaxSlot){const d=Y.drills.find(x=>String(x.id)===routeId)||Y.drills[0];state.notes['syntax-'+d.id+'-'+t.dataset.syntaxSlot]=t.value;save()}if(t.id==='global-search')search(t.value);if(t.id==='module-search')$$('.module-card').forEach(x=>x.hidden=!fold(x.dataset.text).includes(fold(t.value)));if(t.id==='case-search')applyCaseFilters();if(t.id==='source-search')filterSources();if(t.dataset.caseNote){state.notes[t.dataset.caseNote]=t.value;save()}if(t.dataset.editor){state.editors[t.dataset.editor]=t.value;save()}if(t.dataset.skill){state.skills[t.dataset.skill]=Number(t.value);$(`#value-${t.dataset.skill}`).textContent=t.value+'/4';save()}});
document.addEventListener('change',async e=>{const t=e.target;if(t.dataset.lesson){state.done[t.dataset.lesson]=t.checked;save();refreshChrome();toast(t.checked?'Lição praticada. Tente recuperá-la amanhã.':'Lição voltou para sua lista.')}if(['case-category','case-level'].includes(t.id))applyCaseFilters();if(t.id==='source-kind')filterSources();if(t.dataset.score){state.scores[t.dataset.score]=Number(t.value);save()}if(['review-mode','review-category'].includes(t.id)){reviewMode=$('#review-mode').value;reviewCategory=$('#review-category').value;flashIndex=0;flashShown=false;updateFlash()}if(t.id==='restore-file'&&t.files[0]){try{if(t.files[0].size>5000000)throw Error('Arquivo muito grande');const v=JSON.parse(await t.files[0].text());if(v.app!=='staff-lab')throw Error('Formato inválido');const restored=sanitizeState(v.state);if(!confirm('Restaurar este backup substitui o progresso atual deste navegador. Continuar?'))return;state=restored;save();render();toast('Progresso restaurado.')}catch{toast('Não foi possível importar. Use um backup JSON do Staff Lab.')}t.value=''}});
document.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))return;if(e.key==='/'&&!$('#search-dialog').open){e.preventDefault();openSearch()}if(route==='review'&&!$('#search-dialog').open){if(e.code==='Space'){e.preventDefault();flashShown=!flashShown;updateFlash()}if(['1','2','3','4'].includes(e.key))rateCard(Number(e.key)-1)}});
for(const d of $$('dialog'))d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}});
window.addEventListener('hashchange',()=>{if(!location.hash.startsWith('#simulations/'))timer.running=false;render()});
render();
